def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))

    def preorder_of_random_bst(vals):
        # insert in the given order, return the iterative preorder
        left, right = {}, {}
        root = vals[0]
        for x in vals[1:]:
            cur = root
            while True:
                if x < cur:
                    if cur in left:
                        cur = left[cur]
                    else:
                        left[cur] = x
                        break
                else:
                    if cur in right:
                        cur = right[cur]
                    else:
                        right[cur] = x
                        break
        out, st = [], [root]
        while st:
            v = st.pop()
            out.append(v)
            if v in right:
                st.append(right[v])
            if v in left:
                st.append(left[v])
        return out

    tests = [
        fmt([1]),
        fmt([1, 2]),
        fmt([2, 1]),
        fmt([2, 1, 3]),
        fmt([2, 3, 1]),
        fmt([3, 1, 4, 2]),
        fmt([5, 2, 1, 3, 6, 4]),
        fmt([5, 2, 6, 1, 3]),
    ]
    for n in (2, 3, 4, 5, 6, 7, 9, 12):
        for _ in range(3):
            vals = rng.sample(range(1, 4 * n + 1), n)
            tests.append(fmt(vals))
        for _ in range(3):
            vals = rng.sample(range(1, 4 * n + 1), n)
            tests.append(fmt(preorder_of_random_bst(vals)))
        for _ in range(2):
            vals = rng.sample(range(1, 4 * n + 1), n)
            p = preorder_of_random_bst(vals)
            i, j = rng.sample(range(n), 2)
            p[i], p[j] = p[j], p[i]
            tests.append(fmt(p))
    N = 100000
    vals = rng.sample(range(1, 10 ** 9 + 1), N)
    p = preorder_of_random_bst(vals)
    tests.append(fmt(p))
    q = p[:]
    q[-1], q[-2] = q[-2], q[-1]
    tests.append(fmt(q))
    tests.append(fmt(list(range(1, N + 1))))
    tests.append(fmt(list(range(N, 0, -1))))
    # descending chain, a right turn after 6, then a value below 6: invalid
    desc = list(range(2 * N, 0, -2))
    tests.append(fmt(desc[:-2] + [desc[-3] + 1, desc[-3] - 1]))
    # zig-zag deep tree: valid
    lo, hi = 1, N
    zig, flip = [], True
    while lo <= hi:
        if flip:
            zig.append(lo)
            lo += 1
        else:
            zig.append(hi)
            hi -= 1
        flip = not flip
    tests.append(fmt(zig))
    return tests

